SELECT 
FROM tree
WHERE is_delete = 0

    AND family = #{family}


    AND genus = #{genus}


    AND species = #{species}

ORDER BY tree_code

SELECT DISTINCT species FROM tree
WHERE is_delete = 0
  AND family = #{family}
  AND genus = #{genus}
  AND species IS NOT NULL AND species != ''
ORDER BY species

SELECT 
FROM tree
WHERE is_delete = 0

    AND family = #{family}


    AND genus = #{genus}


    AND species = #{species}


    AND protection_level = #{protectionLevel}


    AND age >= #{minAge}


    AND age <= #{maxAge}

ORDER BY tree_code
